-- ---------- 示例:自动任务跑一个 demo Go 扩展(替代存储过程) ----------
INSERT INTO sys_schedule (NAME, DISPLAY_NAME, ACTION_TYPE, ACTION_CONTENT, CRON, IS_ACTIVE, DESCRIPTION, CREATE_TIME)
SELECT '示例-调用Go扩展(替代存储过程)', 'Demo Go Extension', 'go', 'CRUD_SUBMIT_DEMO', '0 * * * *', 'N', '每分钟调用一次演示扩展;IS_ACTIVE=Y时到期自动执行', NOW()
WHERE NOT EXISTS (SELECT 1 FROM sys_schedule WHERE ACTION_CONTENT='CRUD_SUBMIT_DEMO');